    $target_file = $target_dir . Uniqid() . '.' . $imageFileType;
  }

  // Check file size
  if ($_FILES["images"]["size"][$key] > 500000) {
    echo "Error: File is too large.";
    exit();
  }

  // Allow certain file formats
  if($imageFileType != "jpg" && $imageFileType != "png" && $imageFileType != "jpeg"
  && $imageFileType != "gif" ) {
    echo "Error: Only JPG, JPEG, PNG & GIF files are allowed.";
    exit();
  }

  // If all validation checks pass, move the uploaded file to the target directory
  if (move_uploaded_file($_FILES["images"]["tmp_name"][$key], $target_file)) {
    // Create a thumbnail of the uploaded image
    $thumb = $target_dir . 'thumb_' . Uniqid() . '.' . $imageFileType;
    create_thumbnail($target_file, $thumb, 200);
    // Display the thumbnail of the uploaded image
    echo "<img src='". $thumb ."' />";
  } else {
    echo "Error: There was an error uploading your file.";
  }
}

// Function to create thumbnail of uploaded image
function create_thumbnail($source, $destination, $max_size) {
  $img = imagecreatefromjpeg($source);

  $width = imagesx($img);
  $height = imagesy($img);

  $new_width = $max_size;
  $new_height = floor($height * ($max_size / $width));

  $tmp_img = imagecreatetruecolor($new_width, $new_height);
  imagecopyresampled($tmp_img, $img, 0, 0, 0, 0, $new_width, $new_height, $width, $height);

  imagejpeg($tmp_img, $destination, 80);

  imagedestroy($tmp_img);
}
?>
``` 

This script first defines the folder where we want to save the uploaded images. It then checks if the folder exists, and creates it if it doesn't. 

The script then loops through each uploaded file and performs various validation checks. First, it checks if the file is a valid image by calling the `getimagesize` function. If the file is not a valid image, it presents an error message and exits the script. 

Next, the script checks if the file already exists in the target directory. If it does, it generates a unique identifier to prevent overwriting the existing file. 

Then, the script checks the file size and file type. It only allows files with certain extensions (JPG, JPEG, PNG or GIF) and sets a maximum file size of 500kb. If any validation checks fail, an error message is presented and the script exits. 

If all validation checks pass, the script moves the uploaded file to the target directory and generates a thumbnail of the image, using PHP's built-in `imagecreatefromjpeg` and `imagecopyresampled` functions to create a resized thumbnail image. The thumbnail is then displayed as HTML output. 

