function maxSubarray($arr, $diff) {
    $n = count($arr);
    $maxLen = 0;
    $len = 1;
    for ($i = 0; $i < $n - 1; $i++) {
        if (abs($arr[$i + 1] - $arr[$i]) == $diff) {
            $len++;
        } else {
            if ($len > $maxLen) {
                $maxLen = $len;
            }
            $len = 1;
        }
    }
