```
import java.io.BufferedReader;
import java.io.FileReader;
import java.io.IOException;
import java.text.NumberFormat;
import java.util.Locale;

public class ProductRevenue {

    public static void main(String[] args) {
        // check if the CSV file path is provided
        if (args.length < 1) {
            System.err.println("Usage: java ProductRevenue <csv-file>");
            System.exit(1);
        }
        // open the CSV file for reading
        try (BufferedReader input = new BufferedReader(new FileReader(args[0]))) {
            // read and skip the first line (header)
            String line = input.readLine();
            // parse each product data and calculate revenue
            double totalRevenue = 0.0;
            while ((line = input.readLine()) != null) {
                String[] fields = line.split(",");
                int id = Integer.parseInt(fields[0].trim());
                String name = fields[1].trim();
                int quantity = Integer.parseInt(fields[2].trim());
                double price = Double.parseDouble(fields[3].trim());
                double revenue = quantity * price;
                totalRevenue += revenue;
                System.out.printf("%d. %s: %d x %.2f = %.2f%n", id, name, quantity, price, revenue);
            }
            // display the total revenue with proper formatting
            NumberFormat currencyFormat = NumberFormat.getCurrencyInstance(Locale.US);
            System.out.println("Total revenue: " + currencyFormat.format(totalRevenue));
        } catch (IOException | NumberFormatException ex) {
            System.err.println("Error: " + ex.getMessage());
            System.exit(2);
        }
    }
}
