  if (includeSymbols) {
    allChars += symbolChars;
  }

  var password = "";
  for (var I = 0; I < length; i++) {
    var randomChar = allChars.charAt(Math.floor(Math.random() * allChars.length));
    password += randomChar;
  }

  // ensure password does not contain easily guessable words or patterns
  if (/qwerty/i.test(password) || /password/i.test(password)) {
    return generatePassword(length, includeUppercase, includeLowercase, includeNumbers, includeSymbols);
  }

  return password;
}
