Public class ReverseStringRecursive {

    /**
     * This function takes a string input and returns the reversed version of the
     * same string using recursion
     * 
     * @param str the input string to be reversed
     * @return the reversed version of the input string
     */
    public static String reverseString(String str) {
        // base case 1: if the input string is empty or null, return it as is
        if (str == null || str.length() == 0) {
            return str;
        }
        // base case 2: if the input string has only one character, return it as is
        if (str.length() == 1) {
            return str;
        }
        // recursive case: call the function recursively with the substring from the
        // second character to the end
        // and concatenate the first character at the end
        return reverseString(str.substring(1)) + str.charAt(0);
    }

    public static void main(String[] args) {
        String str = "hello world";
        System.out.println("Input: " + str);
        System.out.println("Output: " + reverseString(str));
    }
}

