Here is a sample implementation of a Java program that utilizes the RSA algorithm to generate and verify digital signatures for a simple text file:

```java
import java.io.*;
import java.security.*;

public class DigitalSignatureDemo {
    public static void main(String[] args) {
        // Prompt the user to input the file name
        System.out.print("Enter the name of the file to sign: ");
        Scanner scanner = new Scanner(System.in);
        String fileName = scanner.nextLine();

        try {
            // Read the file content
            File file = new File(fileName);
            FileInputStream fileInputStream = new FileInputStream(file);
            byte[] fileData = new byte[(int) file.length()];
            fileInputStream.read(fileData);
            fileInputStream.close();

            // Generate the RSA key pair
            KeyPairGenerator keyPairGenerator = KeyPairGenerator.getInstance("RSA");
            keyPairGenerator.initialize(2048);
            KeyPair keyPair = keyPairGenerator.generateKeyPair();

            // Sign the file content using the private key
            Signature signature = Signature.getInstance("SHA256withRSA");
            signature.initSign(keyPair.getPrivate());
            signature.update(fileData);
            byte[] digitalSignature = signature.sign();

            // Write the digital signature to a separate file
            String signatureFileName = fileName + ".sig";
            FileOutputStream signatureOutputStream = new FileOutputStream(signatureFileName);
            signatureOutputStream.write(digitalSignature);
            signatureOutputStream.close();

            // Prompt the user to input the original file name and the signature file name for verification
            System.out.print("Enter the name of the original file: ");
            String originalFileName = scanner.nextLine();
            System.out.print("Enter the name of the signature file: ");
            String signatureFileName = scanner.nextLine();

            // Read the original file content
            File originalFile = new File(originalFileName);
            FileInputStream originalInputStream = new FileInputStream(originalFile);
            byte[] originalData = new byte[(int) originalFile.length()];
            originalInputStream.read(originalData);
            originalInputStream.close();

            // Read the digital signature file content
            File signatureFile = new File(signatureFileName);
            FileInputStream signatureInputStream = new FileInputStream(signatureFile);
            byte[] signatureData = new byte[(int) signatureFile.length()];
            signatureInputStream.read(signatureData);
            signatureInputStream.close();

            // Verify the digital signature using the public key
            Signature signatureVerifier = Signature.getInstance("SHA256withRSA");
            signatureVerifier.initVerify(keyPair.getPublic());
            signatureVerifier.update(originalData);
            boolean verified = signatureVerifier.verify(signatureData);

            if (verified) {
                System.out.println("Digital signature is valid.");
            } else {
                System.out.println("Digital signature is invalid.");
            }
        } catch (NoSuchAlgorithmException e) {
            System.err.println("Error: " + e.getMessage());
        } catch (InvalidKeyException e) {
            System.err.println("Error: " + e.getMessage());
        } catch (SignatureException e) {
            System.err.println("Error: " + e.getMessage());
        } catch (IOException e) {
            System.err.println("Error: " + e.getMessage());
        }
    }
}
```

