    double max_val = 0.0;
    int max_row = current_row;

    for (int I = current_row; I < n; i++)
    {
        if (abs(matrix[i][current_row]) > max_val)
        {
            max_val = abs(matrix[i][current_row]);
            max_row = i;
        }
    }

    if (max_val < epsilon)
    {
        return -1; // no pivot element found
    }

    return max_row;
}

void swap_rows(vector<vector<double>>& matrix, int i, int j)
{
    int n = matrix[0].size();

    for (int k = 0; k <= n; k++)
    {
        double temp = matrix[i][k];
        matrix[i][k] = matrix[j][k];
        matrix[j][k] = temp;
    }
}

void gaussian_elimination(vector<vector<double>>& matrix)
{
    int n = matrix.size();

    for (int I = 0; I < n; i++)
    {
        int pivot_row = find_pivot(matrix, i);
        if (pivot_row < 0)
        {
            cout << "No unique solution exists." << endl;
            return;
        }
        if (pivot_row != i)
        {
            swap_rows(matrix, i, pivot_row);
        }

        for (int j = I + 1; j < n; j++)
        {
            double factor = matrix[j][i] / matrix[i][i];
            matrix[j][i] = 0.0;

            for (int k = I + 1; k <= n; k++)
            {
                matrix[j][k] -= factor * matrix[i][k];
            }
        }
    }

    // Backward substitution
    for (int I = n - 1; I >= 0; i--)
    {
        if (abs(matrix[i][i]) < epsilon)
        {
            cout << "No unique solution exists." << endl;
            return;
        }

        for (int j = I - 1; j >= 0; j--)
        {
            double factor = matrix[j][i] / matrix[i][i];
            matrix[j][i] = 0.0;

            for (int k = I + 1; k <= n; k++)
            {
                matrix[j][k] -= factor * matrix[i][k];
            }
        }

        double divisor = matrix[i][i];
        for (int k = i; k <= n; k++)
        {
            matrix[i][k] /= divisor;
        }
    }
}

int main()
{
    int n;
    cout << "Enter the number of variables: ";
    cin >> n;

    vector<vector<double>> matrix(n, vector<double>(n + 1));
    cout << "Enter the augmented matrix:" << endl;

    for (int I = 0; I < n; i++)
    {
        for (int j = 0; j <= n; j++)
        {
            cin >> matrix[i][j];
        }
    }

    gaussian_elimination(matrix);

    cout << "Reduced row echelon form:" << endl;
    print_matrix(matrix);

    return 0;
}
```

The program first takes input of the number of variables, `n`, and then reads in the augmented matrix representing the system of linear equations. It then applies the Gaussian elimination method with pivoting to reduce the matrix to row echelon form, and subsequently to reduced row echelon form. If at any point there are no pivot elements in a column, the program outputs that no unique solution exists. Finally, it prints the reduced row echelon form of the matrix.

The `find_pivot` function searches for the row with the maximum absolute value in the current column (starting from the `current_row`), which is used as the pivot element. The `swap_rows` function swaps two rows in the matrix.

The `gaussian_elimination` function first applies forward elimination by subtracting multiples of the pivot row from subsequent rows to eliminate the corresponding column elements. If a pivot element is found to be zero or near-zero, the program outputs that no unique solution exists. It then applies backward substitution to solve for the variables, starting from the bottom row and working its way up.

