Use v6;

sub MAIN(Str $filename) {

    # Define common stop words
    my @stop_words = ("the", "and", "or");

    # Open the file for reading
    my $file = try open($filename, :r) or die "Could not open file: $!";

    # Declare a hash to store the word counts
    my %word_counts;

    # Read in the file line by line
    for $file.lines -> $line {

        # Split the line into individual words using a regex
        my @words = $line.comb(/<word>+/, :match);

        # Count the frequency of each unique word
        for @words -> $word {
            # Ignore case sensitivity
            $word = lc($word);

            # Ignore common stop words
            next if $word ~~ @stop_words;

            # Increment the word count in the hash
            %word_counts{$word}++;
        }
    }

    # Close the file
    $file.close;

    # Calculate the total number of words
    my $total_words = [+] %word_counts.values;

    # Sort the word counts by frequency in descending order
    my @sorted_word_counts = %word_counts.pairs.sort({ - $^b.value <=> $^a.value });

    # Print out the results with frequency and percentage of total
    for @sorted_word_counts -> $pair {
        my ($word, $count) = $pair;

        # Calculate the percentage of total words represented by this word
        my $percent = $count * 100 / $total_words;

        say "$word\t$count\t($percent%)";
    }
}

