```rust
use reqwest::{error, response};

#[derive(debug)]
pub enum httpmethod {
    get,
    post,
    put,
    delete,
}

#[derive(debug)]
pub struct httprequest {
    method: httpmethod,
    url: string,
    headers: vec<(string, string)>,
    body: option<string>,
}

impl httprequest {
    pub fn new(method: httpmethod, url: string) -> self {
        self {
            method,
            url,
            headers: vec::new(),
            body: none,
        }
    }

    pub fn with_headers(mut self, headers: vec<(string, string)>) -> self {
        self.headers = headers;
        self
    }

    pub fn with_body(mut self, body: string) -> self {
        self.body = some(body);
        self
    }

    pub async fn execute(&self) -> result<response, error> {
        let client = reqwest::client::new();
        let mut request_builder = match self.method {
            httpmethod::get => client.get(self.url.as_str()),
            httpmethod::post => client.post(self.url.as_str()),
            httpmethod::put => client.put(self.url.as_str()),
            httpmethod::delete => client.delete(self.url.as_str()),
        };

        for header in self.headers.iter() {
            request_builder = request_builder.header(&header.0, &header.1);
        }

        match &self.body {
            some(body) => request_builder.body(body.clone()),
            none => request_builder,
        }
        .send()
        .await
    }
}
