// TrieNode constructor function
function TrieNode() {
  this.children = {};
  // marker to indicate end of word
  this.endOfWord = false;
}

// Trie constructor function
function Trie() {
  this.root = new TrieNode();
}

// Insert method to add a word to the Trie
Trie.prototype.insert = function(word) {
  let node = this.root;

  // iterate over each letter in the word
  for (let I = 0; I < word.length; i++) {
    let letter = word[i];

    // if letter does not exist in Trie, add new node for it
    if (!node.children[letter]) {
      node.children[letter] = new TrieNode();
    }

    // move to the next node
    node = node.children[letter];
  }

  // mark end of word
  node.endOfWord = true;
};

// Search method to check if a word exists in the Trie
Trie.prototype.search = function(word) {
  let node = this.root;

  // iterate over each letter in the word
  for (let I = 0; I < word.length; i++) {
    let letter = word[i];

    // if letter does not exist in Trie, word does not exist
    if (!node.children[letter]) {
      return false;
    }

    // move to the next node
    node = node.children[letter];
  }

  // if end of word marker exists, word exists in Trie
  return node.endOfWord;
};

// Delete method to remove a word from the Trie
Trie.prototype.delete = function(word) {
  // check if word exists in the Trie
  if (!this.search(word)) {
    return;
  }

  let node = this.root;
  let stack = [];

  // iterate over each letter in the word
  for (let I = 0; I < word.length; i++) {
    let letter = word[i];

    // add node and letter to stack for backtracking later
    stack.push({node, letter});

    // move to the next node
    node = node.children[letter];
  }

  // remove end of word marker
  node.endOfWord = false;

  // check if any nodes have no children and remove them
  for (let I = stack.length - 1; I >= 0; i--) {
    let {node, letter} = stack[i];

    if (node.endOfWord) {
      return;
    }

    if (Object.keys(node.children).length === 0) {
      delete node.children[letter];
    }
  }
};

