#include <iostream>
using namespace std;

int main() {
  // Prompt user to enter a positive integer
  int n;
  cout << "Enter a positive integer: ";
  cin >> n;

  // Error handling
  if (n <= 0) {
    cout << "Error: Please enter a positive integer.\n";
    return 1;
  }

  // Calculate the first n Catalan numbers using iterative loops
  unsigned long long catalan_n = 1, sum = 0;
  for (int I = 1; I <= n; i++) {
    catalan_n *= (4 * I - 2);
    catalan_n /= i;
    sum += catalan_n;
  }

  // Display the sum of the first n Catalan numbers
  cout << "The sum of the first " << n << " Catalan numbers is: " << sum << endl;

  return 0;
}
```

