using System;

namespace PrimeNumberSum
{
    class Program
    {
        static void Main(string[] args)
        {
            Console.WriteLine("Enter the lower bound of the range:");
            string lowerInput = Console.ReadLine(); // get the lower bound input from the user
            int lower;
            if (!int.TryParse(lowerInput, out lower)) // check if the input can be converted to an integer
            {
                Console.WriteLine("Invalid input. Please enter an integer for the lower bound.");
                return;
            }

            Console.WriteLine("Enter the upper bound of the range:");
            string upperInput = Console.ReadLine(); // get the upper bound input from the user
            int upper;
            if (!int.TryParse(upperInput, out upper)) // check if the input can be converted to an integer
            {
                Console.WriteLine("Invalid input. Please enter an integer for the upper bound.");
                return;
            }

            if (upper < lower) // check if the upper bound is less than the lower bound
            {
                Console.WriteLine("Invalid input. The upper bound cannot be less than the lower bound.");
                return;
            }

            int primeSum = 0; // initialize the sum of prime numbers to 0

            for (int number = lower; number <= upper; number++) // loop through each number in the range
            {
                if (IsPrime(number)) // check if the number is prime
                {
                    primeSum += number; // add the prime number to the sum
                }
            }

            Console.WriteLine("The sum of all prime numbers between {0} and {1} is {2}.", lower, upper, primeSum);
        }

        // method to determine if a number is prime
        static bool IsPrime(int number)
        {
            if (number <= 1) // 1 and smaller numbers are not prime
            {
                return false;
            }

            for (int divisor = 2; divisor <= Math.Sqrt(number); divisor++) // loop through each divisor up to the square root of the number
            {
                if (number % divisor == 0) // if the number is divisible by a divisor, it is not prime
                {
                    return false;
                }
            }

            return true; // if no divisors were found, the number is prime
        }
    }
}
