(function($) {
  $.fn.customanimations = function(options) {

    // default options
    var settings = $.extend({
      animation: 'fade',
      duration: 1000,
      easing: 'swing',
      delay: 0
    }, options);

    // define animations
    var animations = {
      fade: {
        in: { opacity: 1 },
        out: { opacity: 0 }
      },
      slide: {
        in: { opacity: 1, left: 0 },
        out: { opacity: 0, left: '-100%' }
      },
      rotate: {
        in: { opacity: 1, transform: 'rotatex(0deg)' },
        out: { opacity: 0, transform: 'rotatex(90deg)' }
      }
    };

    // run animation on each element
    return this.each(function() {
      var $el = $(this);
      var animation = animations[settings.animation];
      var animationin = animation.in;
      var animationout = animation.out;

      // set initial css properties
      $el.css({ opacity: 0, visibility: 'hidden' });

      // add animation classes to element
      $el.addclass('animated');
      $el.addclass('animate-' + settings.animation);

      // set duration, easing, and delay
      $el.css({
        'animation-duration': settings.duration + 'ms',
        'animation-timing-function': settings.easing,
        'animation-delay': settings.delay + 'ms'
      });

      // define callback function
      var animationend = 'animationend webkitanimationend mozanimationend msanimationend oanimationend';
      var callback = function() {
        if ($el.hasclass('animate-in')) {
          $el.css(animationin);
        }
        else if ($el.hasclass('animate-out')) {
          $el.css({ visibility: 'hidden' }).css(animationout);
        }
        $el.removeclass('animated animate-in animate-out');
      };

      // run animation on show/hide
      $el.on('show.bs.modal', function() {
        $el.addclass('animate-in').css({ visibility: 'visible' }).one(animationend, callback);
      });
      $el.on('hide.bs.modal', function() {
        $el.addclass('animate-out').one(animationend, callback);
      });
    });
  };
})(jquery);
```

