// Step 1: Define a quicksort function that takes an array and returns a sorted array
func quicksort(_ array: [Int]) -> [Int] {
    // Step 2: Define the base case where the array is empty or has only 1 element
    guard array.count > 1 else { return array }

    // Step 3: Choose a pivot element, which can be any element in the array
    let pivot = array[array.count/2]

    // Step 4: Divide the array into two sub-arrays, one with elements less than the pivot and one with elements greater than the pivot
    let less = array.filter { $0 < pivot }
    let equal = array.filter { $0 == pivot }
    let greater = array.filter { $0 > pivot }

    // Step 5: Combine the three sub-arrays and recursively sort the less and greater sub-arrays
    return quicksort(less) + equal + quicksort(greater)
}

// Step 6: Define a function that calculates the median of an array using quicksort
func calculateMedian(_ array: [Int]) -> Int {
    // Step 7: Sort the array using quicksort
    let sortedArray = quicksort(array)

    // Step 8: Check if the array has an even or odd number of elements
    if sortedArray.count % 2 == 0 { // even
        let index1 = sortedArray.count/2
        let index2 = index1 - 1
        let median = (sortedArray[index1] + sortedArray[index2])/2
        return median
    } else { // odd
        let index = sortedArray.count/2
        let median = sortedArray[index]
        return median
    }
}

